function base64Ascii(input) {
  const chars = "REDACTED/";
  let out = "";
  for (let i = 0; i < input.length; i += 3) {
    const a = input.charCodeAt(i);
    const b = i + 1 < input.length ? input.charCodeAt(i + 1) : 0;
    const c = i + 2 < input.length ? input.charCodeAt(i + 2) : 0;
    const n = (a << 16) | (b << 8) | c;
    out += chars[(n >> 18) & 63] + chars[(n >> 12) & 63];
    out += i + 1 < input.length ? chars[(n >> 6) & 63] : "=";
    out += i + 2 < input.length ? chars[n & 63] : "=";
  }
  return out;
}
